}

const BellIconButton = React.forwardRef<HTMLButtonElement, BellProps>(function BellIconButton({ count = 0, sound = true, className, onClick, ...props }, ref) {
  const { sfx } = useSound(sound)
  const [rings, setRings] = React.useState(0)
