  return (
    <button
      ref={ref}
      type="button"
      data-slot="mic-button"
      data-notchset=""
      aria-pressed={live}
      onClick={(event) => {
        if (live) sfx.tone(800, 0.1, "sine", 0.05, 0, 400)
        else sfx.tone(500, 0.1, "sine", 0.06, 0, 900)
        setLive(!live)
        onClick?.(event)
